-- TicketBox Load Testing: 10,000 Users Seed Script
-- Generates active AUDIENCE users with LOCAL account credentials
BEGIN;

-- Batch Users: 1 to 1000
ON CONFLICT (email) DO UPDATE SET status = EXCLUDED.status, updated_at = CURRENT_TIMESTAMP;

-- Batch User Accounts: 1 to 1000
ON CONFLICT (id) DO UPDATE SET password_hash = EXCLUDED.password_hash, user_account_status = EXCLUDED.user_account_status, updated_at = CURRENT_TIMESTAMP;

